DO $admin_user_registry_read_only_204$
DECLARE
  signature_oid oid := to_regprocedure('public.admin_user_registry_page(text,uuid,integer,integer)');
BEGIN
  IF signature_oid IS NULL
     OR has_function_privilege('anon', signature_oid, 'EXECUTE')
     OR has_function_privilege('authenticated', signature_oid, 'EXECUTE')
     OR NOT has_function_privilege('service_role', signature_oid, 'EXECUTE') THEN
    RAISE EXCEPTION 'admin user registry RPC is not service-role-only';
  END IF;
END
$admin_user_registry_read_only_204$;


DO $admin_user_registry_pagination_205$
DECLARE
  definition text := pg_get_functiondef('public.admin_user_registry_page(text,uuid,integer,integer)'::regprocedure);
BEGIN
  IF position('LIMIT (p_page_size + 1)' IN definition) = 0
     OR position('OFFSET (p_page - 1) * p_page_size' IN definition) = 0 THEN
    RAISE EXCEPTION 'admin registry pagination must offset by visible page size';
  END IF;
END
$admin_user_registry_pagination_205$;


DO $admin_user_registry_dual_identity_206$
DECLARE
  definition text := pg_get_functiondef('public.admin_user_registry_page(text,uuid,integer,integer)'::regprocedure);
BEGIN
  IF position('public.user_settings AS learner_profile' IN definition) = 0
     OR position('learner_profile.user_id = account.id' IN definition) = 0 THEN
    RAISE EXCEPTION 'admin registry must retain dual learner/operator profiles';
  END IF;
END
$admin_user_registry_dual_identity_206$;

