DO $probe$
BEGIN
 IF NOT has_function_privilege('authenticated','public.get_meaning_learning_progress_v1(uuid)','EXECUTE') OR has_function_privilege('anon','public.get_meaning_learning_progress_v1(uuid)','EXECUTE') THEN RAISE EXCEPTION 'invalid progress read grants'; END IF;
 IF has_function_privilege('authenticated','public.resume_meaning_learning_as_principal_v1(uuid,uuid,text,uuid)','EXECUTE') OR NOT has_function_privilege('service_role','public.resume_meaning_learning_as_principal_v1(uuid,uuid,text,uuid)','EXECUTE') THEN RAISE EXCEPTION 'invalid meaning resume grants'; END IF;
 IF NOT (SELECT relrowsecurity FROM pg_class WHERE oid='private.meaning_resume_events'::regclass) THEN RAISE EXCEPTION 'resume receipts must retain RLS'; END IF;
END;
$probe$;

DO $probe$
BEGIN
 IF strpos(pg_get_functiondef('private.perform_platform_v2_card_action_without_verifiable_receipt(uuid,text,uuid,text,text,uuid,text,text,uuid,jsonb,text,text)'::regprocedure),'shared-meaning-known:')=0 THEN RAISE EXCEPTION 'missing meaning mutation serialization'; END IF;
END;
$probe$;

DO $probe$
BEGIN
 IF strpos(pg_get_functiondef('public.get_meanings_learning_progress_v1(uuid[])'::regprocedure),'1250')=0
 OR strpos(pg_get_functiondef('public.get_meanings_learning_progress_v1(uuid[])'::regprocedure),'states AS MATERIALIZED')=0
 THEN RAISE EXCEPTION 'invalid bounded set-based meaning progress'; END IF;
 IF strpos(pg_get_functiondef('public.get_meaning_learning_progress_v1(uuid)'::regprocedure),'get_meanings_learning_progress_v1')=0
 THEN RAISE EXCEPTION 'single meaning must share the batch projection'; END IF;
END;
$probe$;

DO $catalog_contract$
DECLARE f pg_proc; definition text;
BEGIN
 SELECT * INTO STRICT f FROM pg_proc WHERE oid='public.get_available_word_lists(uuid,text,text)'::regprocedure;
 definition:=pg_get_functiondef(f.oid);
 IF NOT f.prosecdef OR f.provolatile<>'s' OR NOT ('search_path=public, pg_temp'=ANY(f.proconfig))
 OR has_function_privilege('anon',f.oid,'EXECUTE')
 OR NOT has_function_privilege('authenticated',f.oid,'EXECUTE')
 OR EXISTS(SELECT 1 FROM aclexplode(COALESCE(f.proacl,acldefault('f',f.proowner))) WHERE grantee=0 AND privilege_type='EXECUTE')
 THEN RAISE EXCEPTION 'catalog security contract changed'; END IF;
 IF strpos(definition,'p_user_id IS DISTINCT FROM (select auth.uid())')=0
 OR strpos(definition,'entry_sources AS MATERIALIZED')=0
 OR strpos(definition,'curated_source_counts AS MATERIALIZED')=0
 OR strpos(definition,'can_browse_dictionary')=0
 OR strpos(definition,'AND l.user_id = p_user_id')=0
 OR strpos(definition,'unavailable_source_count')=0
 THEN RAISE EXCEPTION 'catalog identity, availability or ownership contract changed'; END IF;
END;
$catalog_contract$;

DO $progress_contract$
BEGIN
 IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='public'
 AND table_name='user_settings' AND column_name='training_progress_animation'
 AND data_type='text' AND is_nullable='NO' AND column_default='''dots''::text')
 THEN RAISE EXCEPTION 'training progress preference column missing or invalid'; END IF;
 IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='public.user_settings'::regclass
 AND conname='user_settings_training_progress_animation_check' AND contype='c'
 AND pg_get_constraintdef(oid) LIKE '%off%dots%wave%')
 THEN RAISE EXCEPTION 'training progress preference check missing'; END IF;
END;
$progress_contract$;

DO $translation_jobs_contract$
DECLARE f pg_proc; signature text; definition text; privilege text;
BEGIN
 IF NOT EXISTS (SELECT 1 FROM pg_class WHERE oid='public.dictionary_translation_jobs'::regclass AND relrowsecurity)
 THEN RAISE EXCEPTION 'translation queue RLS missing'; END IF;
 IF has_table_privilege('anon','public.dictionary_translation_jobs','SELECT,INSERT,UPDATE,DELETE')
 OR has_table_privilege('authenticated','public.dictionary_translation_jobs','SELECT,INSERT,UPDATE,DELETE')
 OR EXISTS (SELECT 1 FROM pg_class c, LATERAL aclexplode(COALESCE(c.relacl,acldefault('r',c.relowner))) a
 WHERE c.oid='public.dictionary_translation_jobs'::regclass AND a.grantee=0)

 THEN RAISE EXCEPTION 'translation queue privileges changed'; END IF;
 FOREACH privilege IN ARRAY ARRAY['SELECT','INSERT','UPDATE','DELETE'] LOOP
  IF NOT has_table_privilege('service_role','public.dictionary_translation_jobs',privilege)
  THEN RAISE EXCEPTION 'translation worker missing table privilege: %',privilege; END IF;
 END LOOP;
 FOREACH signature IN ARRAY ARRAY[
  'public.dictionary_translation_source_v1(uuid)',
  'public.enqueue_dictionary_translation_job_v1(uuid,text,text,text,text,text,text,integer,boolean,boolean,timestamptz)',
  'public.claim_dictionary_translation_job_v1()',
  'public.heartbeat_dictionary_translation_job_v1(uuid,uuid)',
  'public.fail_dictionary_translation_job_v1(uuid,uuid,text,boolean)',
  'public.complete_dictionary_translation_job_v1(uuid,uuid,jsonb,text)'
 ] LOOP
  SELECT * INTO STRICT f FROM pg_proc WHERE oid=signature::regprocedure;
  IF f.prosecdef OR NOT COALESCE('search_path=public, pg_temp'=ANY(f.proconfig), false)
  OR has_function_privilege('anon',f.oid,'EXECUTE')
  OR has_function_privilege('authenticated',f.oid,'EXECUTE')
  OR NOT has_function_privilege('service_role',f.oid,'EXECUTE')
  OR EXISTS(SELECT 1 FROM aclexplode(COALESCE(f.proacl,acldefault('f',f.proowner))) WHERE grantee=0 AND privilege_type='EXECUTE')
  THEN RAISE EXCEPTION 'translation queue function security changed: %',signature; END IF;
 END LOOP;
 IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='public.dictionary_translation_jobs'::regclass
 AND conname='dictionary_translation_job_identity' AND contype='u')
 OR NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='public.dictionary_translation_jobs'::regclass
 AND conname='dictionary_translation_job_lease' AND contype='c')
 OR NOT EXISTS (SELECT 1 FROM pg_index WHERE indexrelid='public.dictionary_translation_jobs_active_identity_idx'::regclass AND indisunique AND indisvalid)
 THEN RAISE EXCEPTION 'translation queue identity or lease contract missing'; END IF;
 definition:=pg_get_functiondef('public.claim_dictionary_translation_job_v1()'::regprocedure);
 IF strpos(definition,'pg_advisory_xact_lock(674, 1)')=0
 OR strpos(definition,'>= 2')=0 OR strpos(definition,'active.priority = 0')=0
 OR strpos(definition,'attempt < 3')=0 OR strpos(definition,'FOR UPDATE SKIP LOCKED')=0
 THEN RAISE EXCEPTION 'translation queue concurrency or retry contract changed'; END IF;
 definition:=pg_get_functiondef('public.complete_dictionary_translation_job_v1(uuid,uuid,jsonb,text)'::regprocedure);
 IF strpos(definition,'FOR SHARE')=0 OR strpos(definition,'lease_token IS DISTINCT FROM p_lease_token')=0
 OR strpos(definition,'lease_expires_at <= clock_timestamp()')=0
 OR strpos(definition,'source_row_revision IS DISTINCT FROM v_source_revision')=0
 OR strpos(definition,'INSERT INTO public.word_entry_translations')=0
 THEN RAISE EXCEPTION 'translation publication fencing contract changed'; END IF;
END;
$translation_jobs_contract$;

DO $parts$
DECLARE f pg_proc;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM pg_class WHERE oid='public.dictionary_translation_job_parts'::regclass AND relrowsecurity)
 OR has_table_privilege('anon','public.dictionary_translation_job_parts','SELECT,INSERT,UPDATE,DELETE')
 OR has_table_privilege('authenticated','public.dictionary_translation_job_parts','SELECT,INSERT,UPDATE,DELETE')
 OR EXISTS(SELECT 1 FROM pg_class c,LATERAL aclexplode(COALESCE(c.relacl,acldefault('r',c.relowner))) a WHERE c.oid='public.dictionary_translation_job_parts'::regclass AND a.grantee=0)
 OR NOT has_table_privilege('service_role','public.dictionary_translation_job_parts','SELECT,INSERT,UPDATE')
 THEN RAISE EXCEPTION 'translation parts security mismatch'; END IF;
 SELECT * INTO STRICT f FROM pg_proc WHERE oid='public.checkpoint_dictionary_translation_part_v1(uuid,uuid,text,text,jsonb,boolean)'::regprocedure;
 IF f.prosecdef OR NOT COALESCE('search_path=public, pg_temp'=ANY(f.proconfig),false)
 OR has_function_privilege('anon',f.oid,'EXECUTE') OR has_function_privilege('authenticated',f.oid,'EXECUTE')
 OR NOT has_function_privilege('service_role',f.oid,'EXECUTE')
 OR EXISTS(SELECT 1 FROM aclexplode(COALESCE(f.proacl,acldefault('f',f.proowner))) WHERE grantee=0 AND privilege_type='EXECUTE')
 THEN RAISE EXCEPTION 'translation parts function security mismatch'; END IF;
 IF position('source_row_revision' IN pg_get_functiondef(f.oid))=0 OR position('lease_expires_at' IN pg_get_functiondef(f.oid))=0
 THEN RAISE EXCEPTION 'translation parts fencing missing'; END IF;
END $parts$;

DO $hide_retired$
DECLARE f pg_proc;
BEGIN
 SELECT * INTO STRICT f FROM pg_proc
 WHERE oid='public.handle_card_review(uuid,uuid,text,text,uuid)'::regprocedure;
 IF position('legacy_hide_disabled' IN f.prosrc)=0
 OR position('legacy_hide_disabled' IN f.prosrc)>position('IF p_turn_id IS NOT NULL THEN' IN f.prosrc)
 OR f.prosrc ~ 'SET hidden = true'
 OR NOT f.prosecdef
 OR NOT COALESCE('search_path=public, pg_temp'=ANY(f.proconfig),false)
 OR has_function_privilege('anon',f.oid,'EXECUTE')
 OR NOT has_function_privilege('authenticated',f.oid,'EXECUTE')
 OR EXISTS(SELECT 1 FROM aclexplode(COALESCE(f.proacl,acldefault('f',f.proowner))) WHERE grantee=0 AND privilege_type='EXECUTE')
 OR position('require_training_pair_available_v1' IN f.prosrc)=0
 OR position('private.training_reference_now_v1()' IN f.prosrc)=0
 OR NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='public.user_card_status'::regclass AND tgname='reject_known_card_scheduler_mutation' AND tgenabled='O')
 OR position('IF p_result = ''freeze'' THEN' IN f.prosrc)=0
 THEN RAISE EXCEPTION 'legacy hide retirement contract mismatch'; END IF;
END $hide_retired$;

DO $secondary_translation$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_schema = 'public' AND table_name = 'user_settings'
      AND column_name = 'secondary_translation_lang' AND data_type = 'text'
      AND is_nullable = 'YES' AND column_default IS NULL
  ) THEN RAISE EXCEPTION 'secondary full-card translation preference contract mismatch'; END IF;
  IF NOT (SELECT relrowsecurity FROM pg_class WHERE oid = 'public.user_settings'::regclass)
  THEN RAISE EXCEPTION 'user_settings must retain RLS'; END IF;
END $secondary_translation$;

DO $postflight$
DECLARE
  config text[];
BEGIN
  SELECT proconfig INTO config
  FROM pg_proc
  WHERE oid = 'private.training_scheduler_candidates_v2(uuid,text[],uuid,text,text,text,uuid[],text[],jsonb,boolean,boolean)'::regprocedure;

  IF config IS NULL OR NOT (config @> ARRAY['enable_nestloop=off']) THEN
    RAISE EXCEPTION 'training scheduler is missing its scoped enable_nestloop=off planner setting';
  END IF;
END;
$postflight$;

